CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT OR IGNORE INTO metadata VALUES ('schema_version','1');
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, source_key TEXT NOT NULL, sha256 TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(source_key,sha256));
CREATE TABLE IF NOT EXISTS pages (document_id TEXT NOT NULL REFERENCES documents(id), page INTEGER NOT NULL CHECK(page>0), status TEXT NOT NULL, reviewed INTEGER NOT NULL DEFAULT 0 CHECK(reviewed IN (0,1)), data TEXT NOT NULL CHECK(json_valid(data)), PRIMARY KEY(document_id,page));
CREATE TABLE IF NOT EXISTS extracted_rows (id TEXT PRIMARY KEY, document_id TEXT NOT NULL, page INTEGER NOT NULL, position INTEGER NOT NULL, classification TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), FOREIGN KEY(document_id,page) REFERENCES pages(document_id,page), UNIQUE(document_id,page,position));
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS permits (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), authority TEXT NOT NULL, number TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(authority,number));
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, permit_id TEXT NOT NULL REFERENCES permits(id), evidence_id TEXT NOT NULL REFERENCES evidence(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS allocation_sets (id TEXT PRIMARY KEY, permit_id TEXT NOT NULL REFERENCES permits(id), evidence_id TEXT NOT NULL REFERENCES evidence(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS milestones (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), evidence_id TEXT NOT NULL REFERENCES evidence(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS coordinates (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), evidence_id TEXT NOT NULL REFERENCES evidence(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS regions (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS coverage (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS review_log (sequence INTEGER PRIMARY KEY AUTOINCREMENT, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, reason TEXT NOT NULL, at TEXT NOT NULL, previous TEXT, current TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS queue (id TEXT PRIMARY KEY, source TEXT NOT NULL, query TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL, cursor INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, lease_until TEXT, error TEXT, data TEXT NOT NULL CHECK(json_valid(data)), UNIQUE(source,query,start,end));
CREATE TABLE IF NOT EXISTS search_pages (job_id TEXT NOT NULL REFERENCES queue(id), cursor INTEGER NOT NULL, fingerprint TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), PRIMARY KEY(job_id,cursor));
CREATE TABLE IF NOT EXISTS validations (id TEXT PRIMARY KEY, document_id TEXT REFERENCES documents(id), kind TEXT NOT NULL, approved INTEGER NOT NULL CHECK(approved IN(0,1)), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE INDEX IF NOT EXISTS event_permit ON events(permit_id);
CREATE INDEX IF NOT EXISTS allocation_permit ON allocation_sets(permit_id);
CREATE INDEX IF NOT EXISTS queue_status ON queue(status,lease_until);
CREATE TABLE IF NOT EXISTS search_runs (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES queue(id), completed_at TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
